const eu={...es,pdf:'docs/manual-uni-explorer-eu.pdf',assets:'assets/help-eu',topics:[]};
const pair=(a,b)=>[a,b];
function topic(id,title,intro,tips,figures,mobileFigures=figures){for(const [n,data]of [es,eu].entries())data.topics.push({id,title:title[n],intro:intro[n],tips:tips.map(x=>x[n]),figures:figures.map(f=>figure(f,n)),mobileFigures:mobileFigures.map(f=>figure(f,n))});}
function fig(raw,caption,selectors,points){return{raw,caption,selectors,points};}
function figure(f,n){return{raw:f.raw,caption:f.caption[n],selectors:[...f.selectors],points:f.points.map(p=>({title:p[0][n],text:p[1][n]}))};}
const p=(a,b,c,d)=>[pair(a,b),pair(c,d)];
