 for(const key of ['figures','mobileFigures']){const figs=data.topics.find(t=>t.id==='profile')[key],f=figs.find(f=>f.raw==='profile-save');const point=f.points.pop();f.selectors.pop();figs.push({raw:'profile-actions',caption:suffix?'Gorde edo ezabatu profila.':'Guardar o borrar el perfil.',selectors:['.profile-actions'],points:[point]});}
